a-study-in-scarlet	sentence_311	lexical	\N	\N	310	{"text": "Tells at a glance different soils from each other.", "section": "section_11", "entities": []}
a-study-in-scarlet	sentence_1448	lexical	\N	\N	1447	{"text": "H.", "section": "section_38", "entities": []}
