a-study-in-scarlet	sentence_626	lexical	\N	\N	625	{"text": "\\"Read it up—you really should.", "section": "section_19", "entities": []}
a-study-in-scarlet	sentence_131	lexical	\N	\N	130	{"text": "Broad, low tables were scattered about, which bristled with retorts, test-tubes, and little Bunsen lamps, with their blue flickering flames.", "section": "section_7", "entities": []}
a-study-in-scarlet	sentence_132	lexical	\N	\N	131	{"text": "There was only one student in the room, who was bending over a distant table absorbed in his work.", "section": "section_7", "entities": []}
a-study-in-scarlet	sentence_133	lexical	\N	\N	132	{"text": "At the sound of our steps he glanced round and sprang to his feet with a cry of pleasure.", "section": "section_7", "entities": []}
