a-study-in-scarlet	sentence_856	lexical	\N	\N	855	{"text": "When I got to the door——\\"", "section": "section_24", "entities": []}
a-study-in-scarlet	sentence_158	lexical	\N	\N	157	{"text": "In an instant the contents assumed a dull mahogany colour, and a brownish dust was precipitated to the bottom of the glass jar.", "section": "section_7", "entities": []}
a-study-in-scarlet	sentence_159	lexical	\N	\N	158	{"text": "\\"Ha!", "section": "section_8", "entities": []}
a-study-in-scarlet	sentence_160	lexical	\N	\N	159	{"text": "ha!\\"", "section": "section_8", "entities": []}
a-study-in-scarlet	sentence_161	lexical	\N	\N	160	{"text": "he cried, clapping his hands, and looking as delighted as a child with a new toy.", "section": "section_8", "entities": []}
a-study-in-scarlet	sentence_162	lexical	\N	\N	161	{"text": "\\"What do you think of that?\\"", "section": "section_8", "entities": []}
a-study-in-scarlet	sentence_163	lexical	\N	\N	162	{"text": "\\"It seems to be a very delicate test,\\" I remarked.", "section": "section_8", "entities": []}
