a-study-in-scarlet	sentence_166	lexical	\N	\N	165	{"text": "The old Guiacum test was very clumsy and uncertain.", "section": "section_8", "entities": []}
a-study-in-scarlet	sentence_167	lexical	\N	\N	166	{"text": "So is the microscopic examination for blood corpuscles.", "section": "section_8", "entities": []}
a-study-in-scarlet	sentence_168	lexical	\N	\N	167	{"text": "The latter is valueless if the stains are a few hours old.", "section": "section_8", "entities": []}
