final-problem	event_9_6	event	\N	The landlord's letter reports that an English lady has arrived and needs an English doctor	8	{"section": "final-problem-section_9", "speakerId": "peter_steiler_elder", "sourceNodes": ["sentence_346", "sentence_347", "sentence_348"], "communicatesContent": "An English lady has arrived at the hotel in the last stage of consumption after a hemorrhage; she had wintered at Davos Platz, is traveling to join her friends at Lucerne, is expected to live only a few hours, and would greatly like to see an English doctor."}
final-problem	event_10_1	event	\N	Watson returns to Meiringen after leaving Holmes	9	{"section": "final-problem-section_10", "speakerId": null, "sourceNodes": ["sentence_352", "sentence_361", "sentence_362"], "communicatesContent": null}
final-problem	event_10_2	event	\N	Watson speaks with the landlord about the letter and the sick Englishwoman	9	{"section": "final-problem-section_10", "speakerId": "watson", "sourceNodes": ["sentence_363", "sentence_365", "sentence_367", "sentence_368", "sentence_369", "sentence_370", "sentence_371", "sentence_372"], "communicatesContent": "I trust that she is no worse? You did not write this? There is no sick Englishwoman in the hotel?"}
final-problem	event_10_3	event	\N	Watson runs back toward Reichenbach Falls	9	{"section": "final-problem-section_10", "speakerId": null, "sourceNodes": ["sentence_373", "sentence_374", "sentence_375", "sentence_376", "sentence_377", "sentence_378", "sentence_379", "sentence_380", "sentence_381", "sentence_382", "sentence_383", "sentence_384"], "communicatesContent": null}
final-problem	event_10_4	event	\N	Watson searches the path and examines the tracks near the fall	9	{"section": "final-problem-section_10", "speakerId": null, "sourceNodes": ["sentence_387", "sentence_388", "sentence_389", "sentence_390", "sentence_391", "sentence_392", "sentence_393", "sentence_394", "sentence_395", "sentence_396", "sentence_397"], "communicatesContent": null}
